fast_pseudocode:
# CORRECT: grid must be a meta-lambda when using autotune
@triton.autotune(configs=[Config({'XBLOCK': 512}), Config({'XBLOCK': 1024}), ...])
@triton.jit
def kernel(..., XBLOCK: tl.constexpr): ...

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']),)  # adapts to chosen XBLOCK
kernel[grid](...)  # launches correct number of blocks

# Intended after: autotune + dynamic grid
@triton.autotune(configs=[Config({'XBLOCK': 1024}, num_warps=8), ...], key=['xnumel'])
@triton.jit
def kernel(...):
    ...

grid = lambda META: (triton.cdiv(xnumel, META['XBLOCK']),)
kernel[grid](...)  # no XBLOCK kwarg; autotune injects it

